type_error <- function(key, kind, values, display) {
    if (kind == "enum") {
        list(code = "E_ENUM", message = paste0(key, ": ", display, " is not one of ", paste(values, collapse = ",")))
    } else {
        list(code = "E_TYPE", message = paste0(key, ": ", display, " is not a valid ", kind))
    }
}
